      }

      int odd_count = 0;
      for (auto const& [key, val] : char_counts) {
        if (val % 2 != 0) {
          odd_count++;
        }
      }

      if (odd_count > 1) {
        valid_partition = false;
        break;
      }
    }

    if (valid_partition) {
      min_n = min(min_n, (int)substrings.size());
    }
  }

  cout << min_n << endl;

  return 0;
}

