        found = true;
        long long current_score = 0;
        for (int row = 0; row < h; ++row) {
          for (int col = 0; col < w; ++col) {
            current_score += A[i + row][j + col];
          }
        }
        max_score = max(max_score, current_score);
      }
    }
  }

  if (found) {
    cout << max_score << endl;
  } else {
    cout << "NA" << endl;
  }

  return 0;
}

