                    }

                    long long initial_max_product = 0;
                    for (int l = 0; l <= n - k; ++l) {
                        long long product = 1;
                        for (int m = 0; m < k; ++m) {
                            product *= initial_cards[l + m];
                        }
                        initial_max_product = max(initial_max_product, product);
                    }

                    if (current_max_product < initial_max_product) {
                        possible_decrease = true;
                        break;
                    }

                    swap(cards[i], cards[j]);
