        x--; 

        bool found = false;
        for (int j = 0; j < shelf.size(); ++j) {
            if (shelf[j] == x) {
                shelf.erase(shelf.begin() + j);
                found = true;
                break;
            }
        }

        if (!found) {
            shelf.push_back(x);
        }

        long long score = 0;
        for (int j = 0; j < shelf.size(); ++j) {
            for (int k = j + 1; k < shelf.size(); ++k) {
